sys_script_include.script:
var ReadEXCEL = Class.create();
ReadEXCEL.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	prepareData: function(row) {
		myData = {};
		myData.name = row['Name'];
		myData.value = row['Value'];
		myData.description = row['Description'];

		return myData;
	},
	getData: function() {
		var id = this.getParameter('sysparm_id');
		var myobjArray = [];
		var attachmentSID = id;

		//var parser = new sn_impex.ScopedGlideExcelParser();
		var parser = new sn_impex.GlideExcelParser();
		var attachment = new GlideSysAttachment();

		// use attachment sys id of an excel file
		var attachmentStream = attachment.getContentStream(attachmentSID);
		parser.parse(attachmentStream);
		while (parser.next()) {
			var row = parser.getRow();
			myobjArray.push(this.prepareData(row));
		}
		return JSON.stringify(myobjArray);
	},
    type: 'ReadEXCEL'
});
